def md(t, fl=3):
    t = t.copy()
    for c in t.columns:
        if t[c].dtype.kind == "f": t[c] = t[c].round(fl)
    return t.to_markdown(index=False)
L = []; w = L.append
# ---------- Test A
bas = df[(df["filter"] == "BASELINE") & (df.part == "ALL")][["cell", "n", "win", "avgR", "pf", "t", "totR", "maxdd"]]
bi = df[(df["filter"] == "BASELINE") & (df.part == "IS")].set_index("cell"); bo = df[(df["filter"] == "BASELINE") & (df.part == "OOS")].set_index("cell")
bas["avgR_IS"] = bas.cell.map(bi.avgR); bas["avgR_OOS"] = bas.cell.map(bo.avgR); bas["n_OOS"] = bas.cell.map(bo.n)
bas["win"] = (bas.win * 100).round(1); bas = bas.rename(columns={"win": "win%", "maxdd": "maxDD_R"})
desk_b = bas[bas.cell.str.contains("desk")]; v4_b = bas[bas.cell.str.contains("v4")]
# per filter aggregated table
def agg(sysn, mode):
    g = f[(f.system == sysn) & (f["mode"] == mode)]
    a = g.groupby("filter").agg(cells=("cell", "size"), mean_dAvgR_IS=("dIS", "mean"), mean_dAvgR_OOS=("dOOS", "mean"), kept_frac_IS=("kept", "mean"), mean_avgR_IS=("avgR_IS", "mean"), best_t_IS=("t_IS", "max"), cells_better_IS=("dIS", lambda x: int((x > 0).sum())), cells_better_OOS=("dOOS", lambda x: int((x > 0).sum())), IS_pass=("is_pass", "sum"), PASS=("PASS", "sum")).reset_index()
    return a.sort_values("mean_dAvgR_IS", ascending=False)
ntests = len(f); npass_is = int(f.is_pass.sum()); npass = int(f.PASS.sum())
w("# Results: pairing filters + macro confluence backtests\n")
